const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define points and date
  const point1 = ee.Geometry.Point([-119.02882425044682, 46.929987337866386]);
  const point2 = ee.Geometry.Point([-119.70997639198902, 43.19114225407087]);
  const date = '2015-11-29';
  const points = [point1, point2];

  // Helper function to check cloud condition for a point
  async function checkPointCloud(point, date) {
    // Try Sentinel-2 first
    let sentinel2 = ee.ImageCollection('COPERNICUS/S2')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(point);
    let sentinel2Size = sentinel2.size().getInfo();

    if (sentinel2Size > 0) {
      let image = sentinel2.first();
      let qa60 = image.select('QA60');
      let result = qa60.reduceRegion({
        reducer: ee.Reducer.first(),
        geometry: point,
        scale: 10
      }).getInfo();
      if (result && result.QA60 !== null) {
        let qaVal = result.QA60;
        // Check bits 10 (opaque cloud) and 11 (cirrus cloud)
        let cloudy = (qaVal & (1024 + 2048)) > 0;
        return { cloudy: cloudy, source: 'Sentinel-2', valid: true };
      }
      return { cloudy: null, source: 'Sentinel-2', valid: false };
    }

    // Fallback to Landsat 8
    let landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(point);
    let landsat8Size = landsat8.size().getInfo();

    if (landsat8Size > 0) {
      let image = landsat8.first();
      let qa = image.select('QA_PIXEL');
      let result = qa.reduceRegion({
        reducer: ee.Reducer.first(),
        geometry: point,
        scale: 30
      }).getInfo();
      if (result && result.QA_PIXEL !== null) {
        let qaVal = result.QA_PIXEL;
        // Check cloud bits (bits 5-6: 00=clear, >0=cloud)
        let cloudBits = (qaVal >> 5) & 3;
        let cloudy = cloudBits > 0;
        return { cloudy: cloudy, source: 'Landsat-8', valid: true };
      }
      return { cloudy: null, source: 'Landsat-8', valid: false };
    }

    return { cloudy: null, source: 'None', valid: false };
  }

  // Check both points
  let results = [];
  for (let i = 0; i < points.length; i++) {
    let result = await checkPointCloud(points[i], date);
    results.push(result);
    console.log(`Point ${i+1}: ${result.source}, Cloudy: ${result.valid ? result.cloudy : 'No valid pixel'}`);
  }

  // 2. Determine final answer
  let imageFound = results.every(r => r.source !== 'None');
  let validPixels = results.every(r => r.valid);

  if (!imageFound) {
    console.log('<answer>C1</answer>');
    return;
  }
  if (!validPixels) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Both points have valid cloud results
  let bothCloudy = results.every(r => r.cloudy === true);
  console.log(bothCloudy ? '<answer>A</answer>' : '<answer>B</answer>');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
